-- P8 content seeds: the Dawnshore launch catalogue — 62 items, 5 loot tables
-- and the 5 Dawnhaven vendors, authored THROUGH the Dawned-Admin item editors
-- and published via publish v1; these rows are that output, frozen for
-- deploys. ON CONFLICT DO NOTHING: a panel-retuned live row must never be
-- reverted by a redeploy. (Doctrine: seed files are append-only history —
-- repairs ship as NEW migrations, never edits.)
-- content_items: 62 published rows
-- content_loot_tables: 5 published rows
-- content_vendors: 5 published rows
-- enemy loot bindings (P8): only applied where a row has none yet
UPDATE "content_enemies" SET "def" = jsonb_set("def", '{loot}', '{"rolls":1,"goldMax":4,"goldMin":1,"tableId":"loot_dawnshore_trash"}'::jsonb) WHERE "id" = 'enemy_shore_glub' AND "status" = 'published' AND COALESCE("def"->'loot', 'null'::jsonb) = 'null'::jsonb;
UPDATE "content_enemies" SET "def" = jsonb_set("def", '{loot}', '{"rolls":1,"goldMax":10,"goldMin":4,"tableId":"loot_dawnshore_spore"}'::jsonb) WHERE "id" = 'enemy_spore_lobber' AND "status" = 'published' AND COALESCE("def"->'loot', 'null'::jsonb) = 'null'::jsonb;
UPDATE "content_enemies" SET "def" = jsonb_set("def", '{loot}', '{"rolls":1,"goldMax":8,"goldMin":3,"tableId":"loot_dawnshore_spore"}'::jsonb) WHERE "id" = 'enemy_young_mushnub' AND "status" = 'published' AND COALESCE("def"->'loot', 'null'::jsonb) = 'null'::jsonb;
